3	import { useState, useEffect, useCallback, useRef } from "react";
4	import Image from "next/image";
5	import Link from "next/link";
6	import { motion, AnimatePresence, useInView } from "motion/react";
7	import {
8	  ArrowRight,
9	  GitCommitHorizontal,
10	  GitPullRequest,
11	  Tag,
12	  ExternalLink,
13	  Linkedin,
14	  Github,
15	} from "lucide-react";
16	import { Button } from "@/components/ui/button";
17	import { useLightbox } from "@/components/landing/LightboxProvider";
18	import { track } from "@/lib/analytics";
19	import { useMotionProps, FADE_UP, FADE } from "@/hooks/use-motion-props";
20	import {
21	  FOUNDER,
22	  TYPEWRITER_PHRASES,
23	  SHIPPED_WORK,
24	} from "@/lib/jeremy-data";
25	import type { GitHubEvent } from "@/app/api/github-activity/route";
26	
27	// ---------------------------------------------------------------------------
28	// Typewriter hook
29	// ---------------------------------------------------------------------------
30	function useTypewriter(
31	  phrases: readonly string[],
32	  typingSpeed = 52,
33	  pauseMs = 2400
34	) {
35	  const [display, setDisplay] = useState("");
36	  const [phraseIdx, setPhraseIdx] = useState(0);
37	  const [charIdx, setCharIdx] = useState(0);
38	  const [deleting, setDeleting] = useState(false);
39	
40	  useEffect(() => {
41	    const phrase = phrases[phraseIdx];
42	    let timer: ReturnType<typeof setTimeout>;
43	
44	    if (!deleting && charIdx < phrase.length) {
45	      timer = setTimeout(() => setCharIdx((i) => i + 1), typingSpeed);
46	    } else if (!deleting && charIdx === phrase.length) {
47	      timer = setTimeout(() => setDeleting(true), pauseMs);
48	    } else if (deleting && charIdx > 0) {
49	      timer = setTimeout(() => setCharIdx((i) => i - 1), typingSpeed / 2);
50	    } else {
51	      setDeleting(false);
52	      setPhraseIdx((i) => (i + 1) % phrases.length);
53	    }
54	
55	    setDisplay(phrase.slice(0, charIdx));
56	    return () => clearTimeout(timer);
57	  }, [charIdx, deleting, phraseIdx, phrases, typingSpeed, pauseMs]);
58	
59	  return display;
60	}
61	
62	// ---------------------------------------------------------------------------
63	// Event icon map
64	// ---------------------------------------------------------------------------
65	const EVENT_ICONS: Record<GitHubEvent["type"], React.ReactNode> = {
66	  push: <GitCommitHorizontal className="h-3.5 w-3.5 flex-shrink-0" aria-hidden="true" />,
67	  pr: <GitPullRequest className="h-3.5 w-3.5 flex-shrink-0" aria-hidden="true" />,
68	  release: <Tag className="h-3.5 w-3.5 flex-shrink-0" aria-hidden="true" />,
69	  star: <Tag className="h-3.5 w-3.5 flex-shrink-0" aria-hidden="true" />,
70	  other: <GitCommitHorizontal className="h-3.5 w-3.5 flex-shrink-0" aria-hidden="true" />,
71	};
72	
73	function timeAgo(iso: string): string {
74	  const secs = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
75	  if (secs < 60) return `${secs}s ago`;
76	  if (secs < 3600) return `${Math.floor(secs / 60)}m ago`;
77	  if (secs < 86400) return `${Math.floor(secs / 3600)}h ago`;
78	  return `${Math.floor(secs / 86400)}d ago`;
79	}
80	
81	// ---------------------------------------------------------------------------
82	// ActivityTicker — pulls from /api/github-activity, cycles every 4 s
83	// ---------------------------------------------------------------------------
84	function ActivityTicker() {
85	  const [events, setEvents] = useState<GitHubEvent[]>([]);
86	  const [idx, setIdx] = useState(0);
87	  const ref = useRef<HTMLDivElement>(null);
88	  const isInView = useInView(ref);
89	
90	  useEffect(() => {
91	    fetch("/api/github-activity")
92	      .then((r) => r.json())
93	      .then((data: GitHubEvent[]) => setEvents(data))
94	      .catch(() => {});
95	  }, []);
96	
97	  // ⚡ Bolt: Pause auto-advance when off-screen to prevent unnecessary re-renders
98	  useEffect(() => {
99	    if (events.length < 2 || !isInView) return;
100	    const t = setInterval(() => setIdx((i) => (i + 1) % events.length), 4000);
101	    return () => clearInterval(t);
102	  }, [events, isInView]);
103	
104	  return (
105	    <div ref={ref} className="flex min-h-[30px] w-full max-w-full items-center justify-center">
106	      {events.length > 0 && (() => {
107	        const ev = events[idx];
108	        return (
109	          <Link
110	            href={ev.url}
111	            target="_blank"
112	            rel="noopener noreferrer"
113	            className="group flex items-center gap-2 rounded-full border border-border/60 bg-elevated/80 backdrop-blur px-3 py-1.5 text-xs text-muted-foreground hover:text-foreground hover:border-primary/40 transition-all duration-200 max-w-full"
114	            aria-label={`Latest activity: ${ev.message} in ${ev.repo}`}
115	          >
116	            <span className="text-primary/70 flex-shrink-0">{EVENT_ICONS[ev.type]}</span>
117	            <span className="font-mono text-[11px] text-primary/80 flex-shrink-0 hidden sm:inline">
118	              {ev.repo}
119	            </span>
120	            <span className="hidden sm:inline text-border/60" aria-hidden="true">/</span>
121	            <AnimatePresence mode="wait">
122	              <motion.span
123	                key={ev.id}
124	                initial={{ opacity: 0, y: 4 }}
125	                animate={{ opacity: 1, y: 0 }}
126	                exit={{ opacity: 0, y: -4 }}
127	                transition={{ duration: 0.25 }}
128	                className="truncate"
129	              >
130	                {ev.message}
131	              </motion.span>
132	            </AnimatePresence>
133	            <span className="ml-auto flex-shrink-0 opacity-50 hidden sm:inline">
134	              {timeAgo(ev.timestamp)}
135	            </span>
136	            <ExternalLink
137	              className="h-3 w-3 opacity-0 group-hover:opacity-50 transition-opacity flex-shrink-0"
138	              aria-hidden="true"
139	            />
140	          </Link>
141	        );
142	      })()}
143	    </div>
144	  );
145	}
146	
147	// ---------------------------------------------------------------------------
148	// WorkCards — carousel of shipped projects pulled from lib/jeremy-data.ts
149	// ---------------------------------------------------------------------------
150	function WorkCards() {
151	  const [active, setActive] = useState(0);
152	  const ref = useRef<HTMLDivElement>(null);
153	  const isInView = useInView(ref);
154	
155	  const prev = useCallback(
156	    () => setActive((i) => (i - 1 + SHIPPED_WORK.length) % SHIPPED_WORK.length),
157	    []
158	  );
159	  const next = useCallback(
160	    () => setActive((i) => (i + 1) % SHIPPED_WORK.length),
161	    []
162	  );
163	
164	  // ⚡ Bolt: Pause auto-advance when off-screen to prevent unnecessary re-renders
165	  useEffect(() => {
166	    if (!isInView) return;
167	    const t = setInterval(next, 5000);
168	    return () => clearInterval(t);
169	  }, [next, isInView]);
170	
171	  const project = SHIPPED_WORK[active];
172	
173	  return (
174	    <div ref={ref} className="relative w-full">
175	      <div className="overflow-hidden rounded-xl border border-border/60 bg-elevated/60 backdrop-blur">
176	        <AnimatePresence mode="wait">
177	          <motion.div
178	            key={active}
179	            initial={{ opacity: 0, x: 16 }}
180	            animate={{ opacity: 1, x: 0 }}
181	            exit={{ opacity: 0, x: -16 }}
182	            transition={{ duration: 0.28, ease: "easeOut" }}
183	            className="p-4"
184	          >
185	            <div className="flex items-start justify-between gap-3">
186	              <div className="min-w-0">
187	                <div className="flex items-center gap-2 mb-2">
188	                  <span className="rounded-md bg-primary/10 px-2 py-0.5 text-[11px] font-medium text-primary">
189	                    {project.category}
190	                  </span>
191	                  <span className="text-[11px] text-muted-foreground">{project.year}</span>
192	                </div>
193	                <p className="font-semibold text-sm text-foreground">{project.name}</p>
194	                <p className="mt-1 text-xs text-muted-foreground leading-relaxed line-clamp-2">
195	                  {project.description}
196	                </p>
197	                <div className="mt-2.5 flex flex-wrap gap-1">
198	                  {project.stack.map((t) => (
199	                    <span
200	                      key={t}
201	                      className="rounded-full border border-border/60 bg-muted/50 px-1.5 py-0.5 text-[10px] text-muted-foreground"
202	                    >
203	                      {t}
204	                    </span>
205	                  ))}
206	                </div>
207	              </div>
208	              <Link
209	                href={project.github}
210	                target="_blank"
211	                rel="noopener noreferrer"
212	                className="flex-shrink-0 rounded-lg p-1.5 text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
213	                aria-label={`View ${project.name} on GitHub`}
214	              >
215	                <ExternalLink className="h-3.5 w-3.5" aria-hidden="true" />
216	              </Link>
217	            </div>
218	          </motion.div>
219	        </AnimatePresence>
220	
221	        {/* Dots + arrows */}
222	        <div className="flex items-center justify-between border-t border-border/40 px-3 py-2">
223	          <div className="flex gap-1" role="tablist" aria-label="Shipped projects">
224	            {SHIPPED_WORK.map((w, i) => (
225	              <button
226	                key={w.slug}
227	                role="tab"
228	                aria-selected={i === active}
229	                aria-label={`View ${w.name}`}
230	                onClick={() => setActive(i)}
231	                className={`h-1.5 rounded-full transition-all duration-200 ${
232	                  i === active
233	                    ? "w-4 bg-primary"
234	                    : "w-1.5 bg-muted-foreground/30 hover:bg-muted-foreground/60"
235	                }`}
236	              />
237	            ))}
238	          </div>
239	          <div className="flex gap-0.5">
240	            <button
241	              onClick={prev}
242	              aria-label="Previous project"
243	              className="rounded-md p-1 text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
244	            >
245	              <ArrowRight className="h-3 w-3 rotate-180" aria-hidden="true" />
246	            </button>
247	            <button
248	              onClick={next}
249	              aria-label="Next project"
250	              className="rounded-md p-1 text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
251	            >
252	              <ArrowRight className="h-3 w-3" aria-hidden="true" />
253	            </button>
254	          </div>
255	        </div>
256	      </div>
257	    </div>
258	  );
259	}
260	
261	// ---------------------------------------------------------------------------
262	// Main Hero
263	// ---------------------------------------------------------------------------
264	export function Hero() {
265	  const { open } = useLightbox();
266	  const mp = useMotionProps(FADE_UP);
267	  const mpFade = useMotionProps(FADE);
268	  const typeText = useTypewriter(TYPEWRITER_PHRASES);
269	
270	  function trackAndOpen(target: "book" | "form" | "email", label: string) {
271	    track("cta_click", { cta_label: label, cta_location: "hero", target });
272	    open(target);
273	  }
274	
275	  return (
