283	      <div className="absolute inset-x-0 top-0 -z-10 h-[520px] bg-dobeu-hero" aria-hidden="true" />
284	
285	      <div className="container max-w-6xl">
286	        {/* Activity ticker */}
287	        <motion.div
288	          initial={mp.initial}
289	          animate={mp.animate}
290	          transition={{ duration: 0.4 }}
291	          className="mb-8 md:mb-10 flex justify-center"
292	        >
293	          <ActivityTicker />
294	        </motion.div>
295	
296	        {/* Split layout: avatar left / copy right */}
297	        <div className="flex flex-col md:flex-row items-center gap-10 md:gap-14 lg:gap-20">
298	
299	          {/* ── Avatar column ── */}
300	          <motion.div
301	            initial={mpFade.initial}
302	            animate={mpFade.animate}
303	            transition={{ duration: 0.55, delay: 0.1 }}
304	            className="flex-shrink-0 flex flex-col items-center gap-5"
305	          >
306	            {/* Photo */}
307	            <div className="relative">
308	              <div
309	                className="absolute inset-0 rounded-full bg-primary/20 blur-2xl scale-110"
310	                aria-hidden="true"
311	              />
312	              <div className="relative h-44 w-44 md:h-56 md:w-56 rounded-full overflow-hidden border-2 border-primary/30 shadow-2xl">
313	                <Image
314	                  src={FOUNDER.avatar}
315	                  alt={`${FOUNDER.name}, ${FOUNDER.title} at Dobeu`}
316	                  fill
317	                  sizes="(max-width: 768px) 176px, 224px"
318	                  className="object-cover object-top"
319	                  priority
320	                />
321	              </div>
322	              {/* Availability dot */}
323	              <span
324	                className="absolute bottom-3 right-3 h-4 w-4 rounded-full border-2 border-background bg-green-400 shadow-[0_0_8px_2px_rgba(74,222,128,0.55)]"
325	                aria-label="Currently available"
326	              />
327	            </div>
328	
329	            {/* Name + socials */}
330	            <div className="text-center">
331	              <p className="font-semibold text-foreground">{FOUNDER.name}</p>
332	              <p className="text-sm text-muted-foreground">{FOUNDER.title}</p>
333	              <div className="mt-2.5 flex items-center justify-center gap-3">
334	                <Link
335	                  href={FOUNDER.linkedin}
336	                  target="_blank"
337	                  rel="noopener noreferrer"
338	                  aria-label="Jeremy Williams on LinkedIn"
339	                  className="text-muted-foreground hover:text-primary transition-colors"
340	                >
341	                  <Linkedin className="h-4 w-4" aria-hidden="true" />
342	                </Link>
343	                <Link
344	                  href={FOUNDER.github}
345	                  target="_blank"
346	                  rel="noopener noreferrer"
347	                  aria-label="Jeremy Williams on GitHub"
348	                  className="text-muted-foreground hover:text-primary transition-colors"
349	                >
350	                  <Github className="h-4 w-4" aria-hidden="true" />
351	                </Link>
352	              </div>
353	            </div>
354	
355	            {/* Work cards (desktop only, below avatar) */}
356	            <div className="hidden md:block w-64 lg:w-72">
357	              <WorkCards />
358	            </div>
359	          </motion.div>
360	
361	          {/* ── Copy column ── */}
362	          <div className="flex-1 text-center md:text-left">
363	            {/* Eyebrow */}
364	            <motion.p
365	              initial={mp.initial}
