22	type Tab = "book" | "form" | "email";
23	
24	interface LightboxCtx {
25	  open: (tab?: Tab) => void;
26	  close: () => void;
27	}
28	
29	const Ctx = React.createContext<LightboxCtx | null>(null);
30	
31	export function useLightbox(): LightboxCtx {
32	  const ctx = React.useContext(Ctx);
33	  if (!ctx) throw new Error("useLightbox must be used inside <LightboxProvider>");
34	  return ctx;
35	}
36	
37	export function LightboxProvider({ children }: { children: React.ReactNode }) {
38	  const [isOpen, setIsOpen] = React.useState(false);
39	  const [tab, setTab] = React.useState<Tab>("book");
40	
41	  const open = React.useCallback((next: Tab = "book") => {
42	    setTab(next);
43	    setIsOpen(true);
44	  }, []);
45	
46	  const close = React.useCallback(() => setIsOpen(false), []);
47	
48	  // ⚡ Bolt: Memoize context value to prevent unnecessary re-renders of consuming components
49	  // when internal state (like isOpen or tab) changes.
50	  const value = React.useMemo(() => ({ open, close }), [open, close]);
51	
52	  return (
53	    <Ctx.Provider value={value}>
54	      {children}
55	
56	      <Dialog open={isOpen} onOpenChange={setIsOpen}>
57	        <DialogContent className="max-w-2xl">
58	          <DialogHeader>
59	            <DialogTitle className="gradient-text">Let&apos;s talk about your project</DialogTitle>
60	            <DialogDescription>
61	              Three ways in — book a call, send the details, or just drop your email. Whichever fits.
62	            </DialogDescription>
63	          </DialogHeader>
64	
65	          <Tabs value={tab} onValueChange={(v) => setTab(v as Tab)} className="mt-2">
66	            <TabsList>
