"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { useLightbox } from "@/components/landing/LightboxProvider";

/**
 * Sticky CTA bar that appears on mobile after the user scrolls past the hero.
 * Hidden on desktop (nav already shows "Book a call").
 */
export function StickyMobileCTA() {
  const { open } = useLightbox();
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    function onScroll() {
      setVisible(window.scrollY > 600);
    }
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  if (!visible) return null;

  return (
    <div
      className="md:hidden fixed bottom-0 inset-x-0 z-40 p-3 glass border-t border-border/60 animate-fade-up"
      role="region"
      aria-label="Quick book a call"
    >
      <Button onClick={() => open("book")} size="lg" className="w-full">
        Book a call
      </Button>
    </div>
  );
}

import type { NextConfig } from "next";

// Build CSP from arrays so each line stays short enough for git diff to
// recognize the file as text (git treats lines >~700 chars as binary).
const csp = {
  default: ["'self'"],
  script: [
    "'self'",
    "'unsafe-inline'",
    "'unsafe-eval'",
    "https://*.posthog.com",
    "https://app.posthog.com",
    "https://cdn.mxpnl.com",
    "https://*.googletagmanager.com",
    "https://www.google-analytics.com",
    "https://js.stripe.com",
    "https://embed.typeform.com",
    "https://*.apollo.io",
    "https://assets.calendly.com",
    "https://www.datadoghq-browser-agent.com",
    "https://va.vercel-scripts.com",
    "https://widget.intercom.io",
    "https://js.intercomcdn.com"
  ],
  connect: [
    "'self'",
    "https://*.supabase.co",
    "wss://*.supabase.co",
    "https://*.posthog.com",
    "https://app.posthog.com",
    "https://api.mixpanel.com",
    "https://api-js.mixpanel.com",
    "https://*.mixpanel.com",
    "https://*.google-analytics.com",
    "https://*.analytics.google.com",
    "https://api.stripe.com",
    "https://m.stripe.network",
    "https://api.apollo.io",
    "https://*.typeform.com",
    "https://api.calendly.com",
    "https://calendly.com",
    "https://browser-intake-datadoghq.com",
    "https://*.browser-intake-datadoghq.com",
    "https://browser-intake-us5-datadoghq.com",
    "https://*.browser-intake-us5-datadoghq.com",
    "https://vitals.vercel-insights.com",
    "https://vercel.live",
    "https://api.intercom.io",
    "https://api-iam.intercom.io",
    "https://api-iam.eu.intercom.io",
    "https://api-ping.intercom.io",
    "https://nexus-websocket-a.intercom.io",
    "https://nexus-websocket-b.intercom.io",
    "https://nexus-europe-websocket.intercom.io",
    "wss://nexus-websocket-a.intercom.io",
    "wss://nexus-websocket-b.intercom.io",
    "https://uploads.intercomcdn.com",
    "https://uploads.intercomusercontent.com"
  ],
  img: ["'self'", "data:", "blob:", "https:"],
  font: [
    "'self'",
    "https://fonts.gstatic.com",
    "data:",
    "https://js.intercomcdn.com",
    "https://fonts.intercomcdn.com"
  ],
  style: [
    "'self'",
    "'unsafe-inline'",
    "https://fonts.googleapis.com",
    "https://embed.typeform.com",
    "https://assets.calendly.com"
  ],
  // frame-src: typeform's embed iframe is hosted on form.typeform.com (not
  // embed.typeform.com — that's just the SDK loader). Wildcard covers both.
  frame: [
    "'self'",
    "https://js.stripe.com",
    "https://hooks.stripe.com",
    "https://*.typeform.com",
    "https://*.apollo.io",
    "https://calendly.com",
    "https://*.calendly.com",
    "https://*.intercom.io",
    "https://*.intercom.com",
    "https://*.intercomcdn.com"
  ]
};

const ContentSecurityPolicy = [
  `default-src ${csp.default.join(" ")}`,
  `script-src ${csp.script.join(" ")}`,
  `connect-src ${csp.connect.join(" ")}`,
  `img-src ${csp.img.join(" ")}`,
  `font-src ${csp.font.join(" ")}`,
  `style-src ${csp.style.join(" ")}`,
  `frame-src ${csp.frame.join(" ")}`,
  "media-src 'self'",
  "worker-src 'self' blob:",
  "object-src 'none'",
  "base-uri 'self'",
  "form-action 'self'",
  "frame-ancestors 'none'",
  "upgrade-insecure-requests"
].join("; ");

const securityHeaders = [
  { key: "Content-Security-Policy", value: ContentSecurityPolicy },
  { key: "Strict-Transport-Security", value: "max-age=63072000; includeSubDomains; preload" },
  { key: "X-Frame-Options", value: "DENY" },
  { key: "X-Content-Type-Options", value: "nosniff" },
  { key: "Referrer-Policy", value: "origin-when-cross-origin" },
  { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=()" },
  { key: "X-DNS-Prefetch-Control", value: "on" }
];

const nextConfig: NextConfig = {
  reactStrictMode: true,
  poweredByHeader: false,
  // Skew Protection: tie the build ID to the Vercel deployment ID so the
  // client and server always agree on which deployment's assets to load.
  // Enabled via "skewProtection": true in vercel.json. Falls back to a
  // timestamp locally where VERCEL_DEPLOYMENT_ID is unset.
  generateBuildId: async () => process.env.VERCEL_DEPLOYMENT_ID ?? `local-${Date.now()}`,
  // Build is a real verifier again: type-check + lint both pass, so failures
  // here should block the build rather than ship silently. (Was temporarily
  // disabled during Phase-1 launch.)
  typescript: {
    ignoreBuildErrors: false
  },
  eslint: {
    ignoreDuringBuilds: false
  },
  experimental: {
    optimizePackageImports: ["lucide-react", "motion", "@radix-ui/react-dialog", "@radix-ui/react-tabs"]
  },
  images: {
    formats: ["image/avif", "image/webp"],
    remotePatterns: [
      { protocol: "https", hostname: "**.supabase.co" },
      { protocol: "https", hostname: "images.unsplash.com" },
      { protocol: "https", hostname: "media.licdn.com", pathname: "/dms/image/**" },
      { protocol: "https", hostname: "hebbkx1anhila5yf.public.blob.vercel-storage.com" },
      // Ported from the (now-removed) next.config.js — needed by /repos:
      { protocol: "https", hostname: "avatars.githubusercontent.com" },
      { protocol: "https", hostname: "github.com" }
    ]
  },
  async headers() {
    return [
      {
        source: "/(.*)",
        headers: securityHeaders
      }
    ];
  },
  async redirects() {
    return [{ source: "/home", destination: "/", permanent: true }];
  },
  async rewrites() {
    // Serve the Terms of Service at the canonical /tos URL (dobeu.net/tos)
    // in every environment (dev + preview + prod), independent of vercel.json.
    return [{ source: "/tos", destination: "/terms" }];
  }
};

export default nextConfig;

"use client";

import { motion } from "motion/react";
import { CalendarCheck, FileText, Rocket } from "lucide-react";
import { useMotionProps, FADE_UP_LG } from "@/hooks/use-motion-props";

const STEPS = [
  {
    icon: CalendarCheck,
    label: "30-min discovery",
    body: "We talk through what you're trying to ship, what's in the way, and whether I'm the right person. No pitch, no slide deck.",
  },
  {
    icon: FileText,
    label: "Scoped proposal",
    body: "Within 48 hours, you get a one-pager: scope, milestones, price, timeline, what I need from you. Approve, decline, or refine.",
  },
  {
    icon: Rocket,
    label: "Ship in 2–6 weeks",
    body: "Daily Loom updates, your private portal for files + invoices, async-first communication. Most projects ship in a single sprint.",
  },
];

export function HowItWorks() {
  const mp = useMotionProps(FADE_UP_LG, "-100px");

  return (
    <section
      id="how"
      aria-labelledby="how-heading"
      className="py-20 md:py-28 bg-secondary/40"
    >
      <div className="container max-w-5xl">
        <div className="text-center mb-12 md:mb-16">
          <h2
            id="how-heading"
            className="font-display text-3xl md:text-5xl font-bold tracking-tight"
          >
            How it works
          </h2>
          <p className="mt-4 text-muted-foreground max-w-2xl mx-auto">
            Three steps. No long contracts, no kickoff theater.
          </p>
        </div>

        <ol className="grid md:grid-cols-3 gap-4 md:gap-6 relative">
          {STEPS.map((step, i) => (
            <motion.li
              key={step.label}
              initial={mp.initial}
              whileInView={mp.whileInView}
              viewport={mp.viewport}
              transition={{ duration: 0.4, delay: i * 0.1 }}
              className="relative rounded-xl border border-border bg-card p-6 md:p-8"
            >
              <div className="flex items-center gap-3 mb-4">
                <span className="inline-flex items-center justify-center h-10 w-10 rounded-full bg-primary text-primary-foreground font-bold">
                  {i + 1}
                </span>
                <step.icon
                  className="h-5 w-5 text-muted-foreground"
                  aria-hidden="true"
                />
              </div>
              <h3 className="font-display text-xl font-semibold mb-2">
                {step.label}
              </h3>
              <p className="text-sm md:text-base text-muted-foreground leading-relaxed">
                {step.body}
              </p>
            </motion.li>
          ))}
        </ol>
      </div>
    </section>
  );
}

