"use client";

import { motion, useScroll, useTransform } from "motion/react";
import { useRef } from "react";
import { ArrowRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useLightbox } from "@/components/landing/LightboxProvider";
import { track } from "@/lib/analytics";
import { useMotionProps, FADE_UP } from "@/hooks/use-motion-props";

export function FinalCTA() {
  const { open } = useLightbox();
  const mp = useMotionProps(FADE_UP);
  const sectionRef = useRef<HTMLElement>(null);
  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ["start end", "center center"],
  });

  // Gradient intensity increases as user scrolls to this section
  const shadowOpacity = useTransform(scrollYProgress, [0, 1], [0.3, 0.8]);

  function trackAndOpen(target: "book" | "form" | "email", label: string) {
    track("cta_click", { cta_label: label, cta_location: "final_cta", target });
    open(target);
  }

  return (
    <section ref={sectionRef} aria-labelledby="cta-heading" className="py-20 md:py-28 relative">
      {/* Gradient overlay that deepens on scroll */}
      <motion.div
        className="absolute inset-0 pointer-events-none rounded-2xl opacity-0"
        style={{
          opacity: shadowOpacity,
          background: "radial-gradient(circle at center, rgba(107, 92, 231, 0.1), transparent 70%)",
        }}
      />
      <div className="container max-w-4xl">
        <motion.div
          initial={mp.initial}
          whileInView={mp.whileInView}
          viewport={mp.viewport}
          transition={{ duration: 0.5 }}
          className="relative overflow-hidden rounded-2xl border-2 border-primary/30 bg-gradient-to-br from-primary/25 via-card to-accent/20 p-8 md:p-14 text-center shadow-2xl hover:shadow-3xl transition-all duration-300"
        >
          {/* Multi-layer depth effect */}
          <div className="absolute inset-0 -z-20 bg-gradient-to-t from-primary/5 via-transparent to-transparent opacity-40" aria-hidden="true" />
          <div className="absolute inset-0 -z-10 bg-dobeu-mesh opacity-80" aria-hidden="true" />
          <div className="absolute -inset-0.5 -z-30 bg-gradient-to-br from-primary/10 to-accent/10 rounded-2xl blur-xl" aria-hidden="true" />
          <h2
            id="cta-heading"
            className="font-display text-3xl md:text-5xl font-extrabold tracking-tight mb-4 text-foreground"
          >
            Let&apos;s build the thing.
          </h2>
          <p className="text-base md:text-lg text-foreground/70 max-w-xl mx-auto mb-8 font-medium">
            30 minutes. No pitch. We&apos;ll figure out together whether I&apos;m the right person to
            ship what you&apos;re trying to ship.
          </p>
          <div className="flex flex-col sm:flex-row gap-3 justify-center">
            <Button
              size="xl"
              onClick={() => trackAndOpen("book", "Book a call")}
              className="w-full sm:w-auto"
            >
              Book a call <ArrowRight className="ml-1 h-4 w-4" />
            </Button>
            <Button
              size="xl"
              variant="outline"
              onClick={() => trackAndOpen("email", "Or just send your email")}
              className="w-full sm:w-auto"
            >
              Or just send your email
            </Button>
          </div>
        </motion.div>
      </div>
    </section>
  );
}

import { createAdminClient } from "@/lib/supabase/server";
import { Inbox, CalendarCheck, Receipt, Users } from "lucide-react";
import { formatCurrency } from "@/lib/utils";

export default async function AdminOverview() {
  const supabase = createAdminClient();

  const [leadsRes, bookingsRes, openInvoicesRes, usersRes] = await Promise.all([
    supabase.from("leads").select("id,email,name,source,first_seen,utm_source").order("first_seen", { ascending: false }).limit(10),
    supabase.from("bookings").select("id,email,name,scheduled_at,status").gte("scheduled_at", new Date().toISOString()).order("scheduled_at").limit(10),
    supabase.from("invoices").select("id,amount_cents,currency,status,due_date").in("status", ["open", "overdue"]),
    supabase.from("profiles").select("id", { count: "exact", head: true })
  ]);

  const recentLeads = leadsRes.data ?? [];
  const bookingFallback =
    !bookingsRes.data
      ? (
          await supabase
            .from("leads")
            .select("id,email,name,first_seen")
            .eq("source", "book")
            .order("first_seen", { ascending: false })
            .limit(10)
        ).data?.map((lead) => ({
          id: lead.id,
          email: lead.email,
          name: lead.name,
          scheduled_at: lead.first_seen
        })) ?? []
      : [];
  const upcomingBookings = bookingsRes.data ?? bookingFallback;
  const openInvoiceTotal = (openInvoicesRes.data ?? []).reduce((sum, i) => sum + i.amount_cents, 0);
  const userCount = usersRes.count ?? 0;

  return (
    <div className="space-y-8">
      <header>
        <h1 className="font-display text-3xl font-bold tracking-tight">Overview</h1>
        <p className="text-muted-foreground mt-1">Everything coming through dobeu.net.</p>
      </header>

      <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <Tile icon={<Inbox />} label="New leads (30d)" value={recentLeads.length.toString()} />
        <Tile icon={<CalendarCheck />} label="Upcoming bookings" value={upcomingBookings.length.toString()} />
        <Tile icon={<Receipt />} label="Open invoice total" value={formatCurrency(openInvoiceTotal)} />
        <Tile icon={<Users />} label="Client users" value={userCount.toString()} />
      </div>

      <section>
        <h2 className="font-display text-xl font-semibold mb-3">Recent leads</h2>
        {recentLeads.length === 0 ? (
          <p className="text-sm text-muted-foreground rounded-lg border border-dashed border-border p-6 text-center">
            No leads yet. As soon as someone submits a form on dobeu.net, they show up here.
          </p>
        ) : (
          <ul className="rounded-lg border border-border divide-y divide-border">
            {recentLeads.map((l) => (
              <li key={l.id} className="p-4 grid grid-cols-[1fr_auto] items-center gap-2">
                <div>
                  <p className="font-medium">{l.name ?? l.email}</p>
                  <p className="text-xs text-muted-foreground">
                    {l.email} · source: <span className="uppercase tracking-wider">{l.source}</span>
                    {l.utm_source && <> · utm: {l.utm_source}</>}
                  </p>
                </div>
                <time className="text-xs text-muted-foreground" dateTime={l.first_seen}>
                  {new Date(l.first_seen).toLocaleDateString()}
                </time>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2 className="font-display text-xl font-semibold mb-3">Upcoming bookings</h2>
        {upcomingBookings.length === 0 ? (
          <p className="text-sm text-muted-foreground rounded-lg border border-dashed border-border p-6 text-center">
            No upcoming bookings yet.
          </p>
        ) : (
          <ul className="rounded-lg border border-border divide-y divide-border">
            {upcomingBookings.map((b) => (
              <li key={b.id} className="p-4 flex justify-between items-center">
                <div>
                  <p className="font-medium">{b.name ?? b.email}</p>
                  <p className="text-xs text-muted-foreground">{b.email}</p>
                </div>
                <time className="text-sm">{new Date(b.scheduled_at).toLocaleString()}</time>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

function Tile({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) {
  return (
    <div className="rounded-xl border border-border bg-card p-5">
      <div className="text-muted-foreground mb-3 h-5">{icon}</div>
      <p className="font-display text-2xl font-bold">{value}</p>
      <p className="text-xs text-muted-foreground mt-1">{label}</p>
    </div>
  );
}

"use client";

import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";

const FAQS = [
  {
    q: "What's the typical engagement size?",
    a: "Most projects land between $5k and $30k. Smaller scoped sprints exist for tight problems; multi-month builds get quoted separately. I send a fixed-scope, fixed-price proposal after the discovery call so you know the number before committing.",
  },
  {
    q: "How fast can you start?",
    a: "Usually within a week of the discovery call. If I'm fully booked I'll say so on the call and recommend someone good — never string you along.",
  },
  {
    q: "Do you do retainers?",
    a: "Occasionally — for ongoing automation work, agent maintenance, or growth engineering. Discovery call is the right place to scope this.",
  },
  {
    q: "Where will the code live?",
    a: "Your GitHub org by default. I work in feature branches with PR review, and you get full admin access on day one. No code held hostage.",
  },
  {
    q: "Do you sign NDAs?",
    a: "Yes — mutual NDA before the proposal step if you need it. Send yours or use mine.",
  },
  {
    q: "Do you take equity?",
    a: "Rarely, and only with a meaningful cash component alongside. Most engagements are cash.",
  },
  {
    q: "Will I be able to maintain what you build?",
    a: "That's the goal. Every deliverable comes with documentation, a Loom walkthrough, and a 2-week support window after handoff. Modern stack means your future hires already know it.",
  },
  {
    q: "Why \"dobeu\"?",
    a: "Two readings at once. Say it out loud — it's my last initial, W, spelled phonetically (\"dub-el-u\"). It's also \"Do Be You\": we handle the technical backend so you get to be you — focused on running your business, not wrangling your stack. The two overlapping circles in the mark are those two meanings merging, with an amber crescent at the intersection where the work happens.",
  },
];

export function FAQ() {
  // JSON-LD for AI Overviews + featured snippets
  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: FAQS.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };

  return (
    <section id="faq" aria-labelledby="faq-heading" className="py-20 md:py-28">
      <div className="container max-w-3xl">
        <div className="text-center mb-12">
          <h2
            id="faq-heading"
            className="font-display text-3xl md:text-5xl font-bold tracking-tight"
          >
            FAQ
          </h2>
        </div>
        <Accordion type="single" collapsible className="w-full">
          {FAQS.map((f, i) => (
            <AccordionItem key={i} value={`item-${i}`}>
              <AccordionTrigger>
                <span>{f.q}</span>
              </AccordionTrigger>
              <AccordionContent>
                <span>{f.a}</span>
              </AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>
      </div>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
    </section>
  );
}

